import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parsePois } from '../src/pois/pois';
import { PRESETS } from '../src/terrain/relief';
import { TOUR_STOPS, resolveTour, tourFlyDuration, tourStep } from '../src/ui/tour';
import { wgs84ToUtm } from '../src/geo';

/** Generated by the pipeline (git-ignored): absent in a clean checkout, e.g. the public Pages CI build. */
const POIS_FILE = join(__dirname, '..', 'public', 'data', 'pois.geojson');
const HAS_POIS = existsSync(POIS_FILE);

const poi = (id: string, lat: number, lon: number) => ({ id, name: id, type: 'other', confidence: 'high', lat, lon }) as never;

describe('tour', () => {
  it('has ~6 stops with short German hypothesis texts and known presets', () => {
    expect(TOUR_STOPS.length).toBeGreaterThanOrEqual(5);
    expect(TOUR_STOPS.length).toBeLessThanOrEqual(8);
    const presetIds = new Set(PRESETS.map((p) => p.id));
    for (const s of TOUR_STOPS) {
      expect(presetIds.has(s.preset)).toBe(true);
      expect(s.text.length).toBeLessThan(260);
      expect(s.dist).toBeGreaterThan(0);
      expect(s.agl).toBeGreaterThan(0);
    }
    // Hypothesis framing: every text hedges (Hypothese / vermutlich / mögliche / deuten / können …).
    for (const s of TOUR_STOPS) expect(s.text).toMatch(/Hypothese|vermutlich|möglich|deute|könn|nicht jede|überlagern/);
    expect(new Set(TOUR_STOPS.map((s) => s.poiId)).size).toBe(TOUR_STOPS.length);
  });

  it.skipIf(!HAS_POIS)('every stop exists in the shipped pois.geojson', () => {
    const fc = JSON.parse(readFileSync(POIS_FILE, 'utf8'));
    const ids = new Set(parsePois(fc).map((p) => p.id));
    for (const s of TOUR_STOPS) expect(ids.has(s.poiId)).toBe(true);
  });

  it('resolves only stops whose POI exists and lies inside the AOI, in tour order', () => {
    const pois = [poi(TOUR_STOPS[2].poiId, 1, 1), poi(TOUR_STOPS[0].poiId, 2, 2), poi('other', 3, 3), poi(TOUR_STOPS[1].poiId, 9, 9)];
    const out = resolveTour(pois, (lat, lon) => ({ E: lat * 10, N: lon * 10 }), (E) => E < 50);
    expect(out.map((s) => s.poiId)).toEqual([TOUR_STOPS[0].poiId, TOUR_STOPS[2].poiId]);
    expect(out[0]).toMatchObject({ E: 20, N: 20, poiName: TOUR_STOPS[0].poiId });
    expect(resolveTour([], () => ({ E: 0, N: 0 }), () => true)).toEqual([]);
    expect(resolveTour(pois, () => ({ E: NaN, N: 0 }), () => true)).toEqual([]);
  });

  it.skipIf(!HAS_POIS)('Karlsberg AOI (3×3 km) gets the palace stops; the overall AOI (6×8 km) gets all of them', () => {
    const fc = JSON.parse(readFileSync(POIS_FILE, 'utf8'));
    const box = (E0: number, N0: number, w: number, h: number) => (E: number, N: number) => E >= E0 && E <= E0 + w && N >= N0 && N <= N0 + h;
    const karlsberg = resolveTour(parsePois(fc), wgs84ToUtm, box(381000, 5465000, 3000, 3000)).map((s) => s.poiId);
    expect(karlsberg).toEqual(['r03-01', 'r03-02', 'r03-04']);
    const overall = resolveTour(parsePois(fc), wgs84ToUtm, box(378000, 5460000, 6000, 8000)).map((s) => s.poiId);
    expect(overall).toEqual(TOUR_STOPS.map((s) => s.poiId));
  });

  it('steps stop at both ends; reduced motion jumps', () => {
    expect(tourStep(0, 1, 3)).toBe(1);
    expect(tourStep(2, 1, 3)).toBe(-1);
    expect(tourStep(0, -1, 3)).toBe(-1);
    expect(tourFlyDuration(true)).toBeLessThan(0.2);
    expect(tourFlyDuration(false)).toBeUndefined();
  });
});
